// Generated by InvokeSmith. Starts the real stdio entrypoint and checks discovery.
import { expect, test } from "bun:test";
import { fileURLToPath } from "node:url";
import { Client } from "@modelcontextprotocol/client";
import { StdioClientTransport } from "@modelcontextprotocol/client/stdio";

test("stdio server starts and exposes every contracted tool", async () => {
  const projectRoot = fileURLToPath(new URL("../", import.meta.url));
  const transport = new StdioClientTransport({
    command: process.execPath,
    args: ["run", "./src/server.ts"],
    cwd: projectRoot,
    stderr: "pipe"
  });
  const client = new Client({ name: "invokesmith-stdio-smoke", version: "0.1.0" });
  try {
    await client.connect(transport);
    const listed = await client.listTools();
    expect(listed.tools.map((tool) => tool.name).sort()).toEqual([
  "dev.smithtasks.tasks.delete",
  "dev.smithtasks.tasks.reschedule",
  "dev.smithtasks.tasks.search"
]);
  } finally {
    await client.close();
  }
});
